const body = $input.first().json.body;
const required = ['item_description', 'quotes'];
const missing = required.filter(f => !body[f]);
if (missing.length) return [{ json: { valid: false, error: `Missing: ${missing.join(', ')}` } }];
if (!Array.isArray(body.quotes) || body.quotes.length < 2) return [{ json: { valid: false, error: 'Need at least 2 quotes to compare' } }];
if (body.quotes.length > 8) return [{ json: { valid: false, error: 'Maximum 8 quotes per comparison' } }];

const quotes = body.quotes.map((q, i) => {
  const unitPrice = parseFloat(q.unit_price) || 0;
  const quantity = parseFloat(body.quantity) || 1;
  const totalPrice = parseFloat(q.total_price) || (unitPrice * quantity);
  const deliveryDays = parseInt(q.delivery_days) || null;
  const deliveryCost = parseFloat(q.delivery_cost) || 0;
  const allInTotal = totalPrice + deliveryCost;
  return {
    id: `Q${i+1}`,
    supplierName: q.supplier_name || `Supplier ${i+1}`,
    unitPrice,
    totalPrice,
    deliveryCost,
    allInTotal: parseFloat(allInTotal.toFixed(2)),
    deliveryDays,
    paymentTerms: q.payment_terms || '',
    warranty: q.warranty || '',
    certifications: q.certifications || '',
    moq: parseInt(q.moq) || null,
    notes: (q.notes || '').slice(0, 400),
    quoteDate: q.quote_date || '',
    validUntil: q.valid_until || ''
  };
});

quotes.sort((a, b) => a.allInTotal - b.allInTotal);
const lowestTotal = quotes[0].allInTotal;
quotes.forEach(q => {
  q.premiumVsLowest = lowestTotal > 0 ? parseFloat(((q.allInTotal - lowestTotal) / lowestTotal * 100).toFixed(1)) : 0;
});

return [{
  json: {
    valid: true,
    itemDescription: body.item_description.trim(),
    quantity: parseFloat(body.quantity) || 1,
    unit: body.unit || 'units',
    currency: body.currency || 'USD',
    priorityFactors: body.priority_factors || 'price, delivery, quality',
    additionalContext: (body.additional_context || '').slice(0, 500),
    replyEmail: body.reply_email || null,
    quotes
  }
}];

values.content:
Compare these supplier quotes and give a recommendation.

Item: {{ $json.itemDescription }}
Quantity: {{ $json.quantity }} {{ $json.unit }}
Currency: {{ $json.currency }}
Priority factors: {{ $json.priorityFactors }}
Additional context: {{ $json.additionalContext || 'none' }}

Quotes (sorted by all-in price):
{{ $json.quotes.map(q => `${q.id}: ${q.supplierName}\n  Unit price: ${$json.currency}${q.unitPrice} | Total: ${$json.currency}${q.totalPrice} | Delivery: ${$json.currency}${q.deliveryCost} | ALL-IN: ${$json.currency}${q.allInTotal} (+${q.premiumVsLowest}% vs lowest)\n  Delivery: ${q.deliveryDays ? q.deliveryDays + ' days' : 'not specified'} | Payment: ${q.paymentTerms || 'not specified'} | Warranty: ${q.warranty || 'none'} | Certs: ${q.certifications || 'none'} | MOQ: ${q.moq || 'none'}\n  Notes: ${q.notes || 'none'}`).join('\n\n') }}

Return this JSON:
{
  "recommendation": "Q1",
  "recommended_supplier": "supplier name",
  "confidence": "high | medium | low",
  "recommendation_rationale": "2-3 sentences — why this quote wins, referencing specific numbers",
  "runner_up": "Q? or null",
  "runner_up_note": "one sentence on when you'd choose runner-up instead — null if clear winner",
  "quote_analysis": [
    {
      "id": "Q1",
      "supplier": "name",
      "verdict": "one of: recommended | strong | acceptable | avoid",
      "pros": ["specific pros"],
      "cons": ["specific cons"],
      "red_flags": ["anything unusual or missing that should concern the buyer — empty array if none"]
    }
  ],
  "negotiation_leverage": "one specific piece of advice on how to negotiate with the recommended supplier using the other quotes as leverage",
  "missing_information": ["things not provided in any quote that you'd want before finalizing — empty if complete"],
  "total_cost_of_ownership_note": "any payment terms, warranty, or hidden cost considerations that affect the real comparison beyond sticker price"
}

