const raw = $input.first().json.text || $input.first().json.content?.[0]?.text || '';
let analysis;
try {
  analysis = JSON.parse(raw.replace(/```json|```/g,'').trim());
} catch(e) {
  return [{ json: { error: 'Parse error', raw } }];
}
const input = $('Validate & Enrich Quotes').first().json;
analysis._meta = { itemDescription: input.itemDescription, quantity: input.quantity, unit: input.unit, currency: input.currency, quotes: input.quotes, replyEmail: input.replyEmail };
return [{ json: analysis }];

const a = $input.first().json;
const m = a._meta;
function esc(s) { return String(s||'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;'); }
const cur = m.currency;

const verdictConfig = { recommended: { color:'#16a34a', bg:'#f0fdf4', label:'Recommended' }, strong: { color:'#2563eb', bg:'#eff6ff', label:'Strong' }, acceptable: { color:'#d97706', bg:'#fffbeb', label:'Acceptable' }, avoid: { color:'#dc2626', bg:'#fef2f2', label:'Avoid' } };
const confColor = { high:'#16a34a', medium:'#d97706', low:'#dc2626' };

const quoteCards = (a.quote_analysis||[]).map(qa => {
  const raw = m.quotes.find(q => q.id === qa.id) || {};
  const vc = verdictConfig[qa.verdict] || verdictConfig.acceptable;
  const isRec = qa.id === a.recommendation;
  return `<div style="border:2px solid ${isRec ? '#16a34a' : '#e5e7eb'};border-radius:8px;margin-bottom:14px;overflow:hidden">
    <div style="background:${isRec ? '#f0fdf4' : '#f9fafb'};padding:10px 16px;display:flex;justify-content:space-between;align-items:center">
      <div>
        <strong style="font-size:14px">${esc(raw.supplierName)}</strong>
        <span style="font-size:12px;color:#9ca3af;margin-left:8px">${qa.id}</span>
        ${isRec ? '<span style="margin-left:8px;font-size:12px;font-weight:700;color:#16a34a">★ RECOMMENDED</span>' : ''}
      </div>
      <div style="text-align:right">
        <div style="font-size:16px;font-weight:700">${cur}${raw.allInTotal}</div>
        ${raw.premiumVsLowest > 0 ? `<div style="font-size:11px;color:#9ca3af">+${raw.premiumVsLowest}% vs lowest</div>` : '<div style="font-size:11px;color:#16a34a">lowest price</div>'}
      </div>
    </div>
    <div style="padding:12px 16px">
      <div style="display:grid;grid-template-columns:1fr 1fr 1fr;gap:10px;font-size:12px;color:#6b7280;margin-bottom:10px">
        <span>Delivery: ${raw.deliveryDays ? raw.deliveryDays+'d' : '?'}</span>
        <span>Terms: ${esc(raw.paymentTerms||'?')}</span>
        <span>Warranty: ${esc(raw.warranty||'none')}</span>
      </div>
      <div style="display:grid;grid-template-columns:1fr 1fr;gap:12px">
        <div><div style="font-size:11px;font-weight:700;text-transform:uppercase;color:#16a34a;margin-bottom:4px">Pros</div>${(qa.pros||[]).map(p=>`<div style="font-size:13px;color:#374151;margin-bottom:3px">+ ${esc(p)}</div>`).join('')}</div>
        <div><div style="font-size:11px;font-weight:700;text-transform:uppercase;color:#dc2626;margin-bottom:4px">Cons</div>${(qa.cons||[]).map(c=>`<div style="font-size:13px;color:#374151;margin-bottom:3px">− ${esc(c)}</div>`).join('')}</div>
      </div>
      ${(qa.red_flags||[]).length ? `<div style="margin-top:10px;background:#fffbeb;border-left:3px solid #f59e0b;padding:8px 12px;border-radius:0 4px 4px 0">${(qa.red_flags||[]).map(rf=>`<div style="font-size:12px;color:#92400e">⚠ ${esc(rf)}</div>`).join('')}</div>` : ''}
    </div>
  </div>`;
}).join('');

const html = `<!DOCTYPE html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"></head>
<body style="margin:0;padding:16px;background:#f9fafb;font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',sans-serif;color:#111">
<div style="max-width:680px;margin:0 auto">
  <div style="background:#111827;color:#fff;padding:20px 26px;border-radius:10px 10px 0 0">
    <div style="font-size:11px;text-transform:uppercase;letter-spacing:1px;color:#6b7280;margin-bottom:5px">Supplier Quote Comparison</div>
    <div style="font-size:18px;font-weight:700">${esc(m.itemDescription)}</div>
    <div style="font-size:13px;color:#9ca3af;margin-top:3px">${m.quantity} ${esc(m.unit)} · ${m.quotes.length} quotes compared</div>
  </div>
  <div style="background:#f0fdf4;padding:16px 26px;border:1px solid #bbf7d0;border-top:none">
    <div style="display:flex;justify-content:space-between;align-items:center">
      <div>
        <div style="font-size:11px;font-weight:700;text-transform:uppercase;color:#15803d;margin-bottom:4px">Recommendation · <span style="color:${confColor[a.confidence]||'#6b7280'}">${esc(a.confidence)} confidence</span></div>
        <div style="font-size:16px;font-weight:700;color:#166534">${esc(a.recommended_supplier)}</div>
        <p style="font-size:14px;color:#374151;margin:6px 0 0;line-height:1.6">${esc(a.recommendation_rationale)}</p>
      </div>
    </div>
    ${a.runner_up_note ? `<div style="margin-top:10px;font-size:13px;color:#4b5563;font-style:italic">Runner-up note: ${esc(a.runner_up_note)}</div>` : ''}
  </div>
  <div style="background:#fff;padding:18px 26px;border:1px solid #e5e7eb;border-top:3px solid #f3f4f6">
    <div style="font-size:11px;font-weight:700;text-transform:uppercase;letter-spacing:0.5px;color:#9ca3af;margin-bottom:12px">Quote by quote</div>
    ${quoteCards}
  </div>
  ${a.negotiation_leverage ? `<div style="background:#eff6ff;padding:14px 26px;border:1px solid #bfdbfe">
    <div style="font-size:11px;font-weight:700;text-transform:uppercase;color:#1d4ed8;margin-bottom:5px">Negotiation leverage</div>
    <div style="font-size:14px;color:#1e40af;line-height:1.6">${esc(a.negotiation_leverage)}</div>
  </div>` : ''}
  ${(a.missing_information||[]).length ? `<div style="background:#fffbeb;padding:14px 26px;border:1px solid #fde68a">
    <div style="font-size:11px;font-weight:700;text-transform:uppercase;color:#92400e;margin-bottom:6px">Before deciding — ask for</div>
    ${(a.missing_information||[]).map(mi=>`<div style="font-size:14px;color:#78350f;padding:3px 0">• ${esc(mi)}</div>`).join('')}
  </div>` : ''}
  ${a.total_cost_of_ownership_note ? `<div style="background:#fff;padding:14px 26px;border:1px solid #e5e7eb;border-top:3px solid #f3f4f6">
    <div style="font-size:11px;font-weight:700;text-transform:uppercase;color:#9ca3af;margin-bottom:5px">Total cost of ownership note</div>
    <div style="font-size:14px;color:#374151;line-height:1.6">${esc(a.total_cost_of_ownership_note)}</div>
  </div>` : ''}
  <div style="background:#111827;color:#4b5563;font-size:11px;padding:12px 26px;border-radius:0 0 10px 10px;font-family:monospace;text-align:center">
    Supplier Quote Comparator · ${new Date().toLocaleDateString()}
  </div>
</div>
</body></html>`;

return [{ json: { html, replyEmail: m.replyEmail, itemDescription: m.itemDescription, recommendedSupplier: a.recommended_supplier, quoteCount: m.quotes.length, analysis: a } }];
